<div class="container-xxl py-3"><h4 class="fw-bold mb-1"><i class="ri-history-line me-1"></i>Log Telegram</h4><p class="text-muted small">Status UNKNOWN adalah terminal dan tidak di-retry otomatis. Resolusi wajib manual, beralasan, dan tercatat.</p><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Waktu</th><th>Target</th><th>Sumber</th><th>Laporan</th><th>Status</th><th>HTTP</th><th>Preview / error</th><th>Resolusi UNKNOWN</th></tr></thead><tbody><?php foreach((array)($logs??[]) as $row): ?><tr><td class="text-nowrap"><?= html_escape($row['created_at']) ?></td><td><?= html_escape($row['target_title']) ?></td><td><?= html_escape($row['source_type']) ?></td><td><?= html_escape($row['report_type']??'-') ?></td><td><span class="badge <?= $row['delivery_status']==='SENT'?'bg-success':($row['delivery_status']==='UNKNOWN'?'bg-warning text-dark':'bg-danger') ?>"><?= html_escape($row['delivery_status']) ?></span></td><td><?= (int)$row['http_code'] ?></td><td><div><?= nl2br(html_escape($row['message_preview']??'')) ?></div><?php if(!empty($row['error_message'])): ?><div class="text-danger small"><?= html_escape($row['error_message']) ?></div><?php endif; ?></td><td><?php if(!empty($row['resolution_action'])): ?><div class="fw-semibold"><?= html_escape($row['resolution_action']) ?></div><div class="small"><?= html_escape($row['resolution_reason']??'') ?></div><div class="text-muted small"><?= html_escape($row['resolved_at']??'') ?> · <?= html_escape($row['resolved_by_username']??('user #'.(int)$row['resolved_by'])) ?><?php if(!empty($row['resolution_queue_id'])): ?> · queue #<?= (int)$row['resolution_queue_id'] ?><?php endif; ?></div><?php elseif(!empty($can_resolve) && ($row['delivery_status']??'')==='UNKNOWN' && ($row['queue_status']??'')==='UNKNOWN'): ?><form method="post" action="<?= site_url('telegram/resolve_unknown') ?>" class="d-flex flex-column gap-1" style="min-width:220px"><input type="hidden" name="tg_unknown_resolution_csrf" value="<?= html_escape($resolution_csrf??'') ?>"><input type="hidden" name="queue_id" value="<?= (int)$row['queue_id'] ?>"><input type="hidden" name="request_id" value="<?= html_escape($resolution_request_id??'') ?>"><select class="form-select form-select-sm" name="action" required><option value="">Pilih tindakan</option><option value="CONFIRM_SENT">Konfirmasi terkirim</option><option value="CLOSE_FAILED">Tutup sebagai gagal</option><option value="RESEND">Buat antrean kirim ulang</option></select><input class="form-control form-control-sm" name="reason" maxlength="500" placeholder="Alasan wajib" required><button class="btn btn-outline-primary btn-sm" type="submit">Simpan resolusi</button></form><?php else: ?>-<?php endif; ?></td></tr><?php endforeach; ?><?php if(empty($logs)): ?><tr><td colspan="8" class="text-center text-muted py-3">Belum ada delivery.</td></tr><?php endif; ?></tbody></table></div></div></div>
